entries[21940] = { ["name"] = "Design: Golden Hare", ["text"] = "Use: Teaches you how to craft a Golden Hare.\nRequires Classic Jewelcrafting (200)\nSell Price:\nFigurine - Golden Hare\nBinds when picked up\nUnique-Equipped\nTrinket\nEquip: Run speed increased slightly.\nUse: Increased speed by 30% and prevents new snares from landing on the user for 6 sec. (20 Min Cooldown)\nRequires Classic Jewelcrafting (200)\nSell Price:\nRequires Gold Bar (6), Citrine (2)\nOptional Reagents: Optional Reagent Slot (#49)" }
