entries[22559] = { ["name"] = "Formula: Enchant Weapon - Mongoose", ["text"] = "Binds when picked up\nUse: Teaches you how to perform the Mongoose enchantment.\nPermanently enchant a melee weapon to occasionally increase Agility by 24 and haste by 6 . Cannot be applied to items higher than level 320.\nRequires Outland Enchanting (75)\nSell Price:" }
